INSERT INTO "_shoe_catalog_import_guard" SELECT CASE WHEN EXISTS(SELECT 1 FROM running_shoes WHERE lower(brand)=lower('Nike') AND lower(model)=lower('Alphafly 4') AND (slug IS NULL OR slug<>'nike-alphafly-4')) THEN 0 ELSE 1 END;
INSERT INTO "_shoe_catalog_import_guard" SELECT CASE WHEN EXISTS(SELECT 1 FROM running_shoes WHERE slug='nike-alphafly-4' AND NOT ("brand" IS 'Nike' AND "model" IS 'Alphafly 4' AND "slug" IS 'nike-alphafly-4' AND "series_name" IS 'Alphafly' AND "version_number" IS 4 AND "category" IS 'racing' AND "weight" IS NULL AND "availability" IS 'upcoming' AND "available_from" IS '2026-10-29' AND "heel_stack_height" IS NULL AND "forefoot_stack_height" IS NULL AND "heel_to_toe_drop" IS 8 AND "cushioning_level" IS 'soft' AND "stability" IS 'neutral' AND "has_carbon_plate" IS 1 AND "has_super_foam" IS 1 AND "price" IS 279.95 AND "best_for" IS '["racing","long_runs"]' AND "release_year" IS 2026 AND "description" IS 'Upcoming marathon racer with ZoomX LT foam, a carbon Flyplate and redesigned Air Zoom units. Running Warehouse lists orders from October 29, 2026; weight and stack measurements are not yet published. Not independently wear-tested.' AND "source_url" IS 'https://www.runningwarehouse.com/Nike_Alphafly_4/descpage-NAFL4M1.html' AND "data_source" IS 'running_warehouse' AND "last_verified" IS '2026-09-26T00:00:00.000Z' AND "durability_rating" IS NULL AND "responsiveness_rating" IS NULL AND "comfort_rating" IS NULL)) THEN 0 ELSE 1 END;
INSERT INTO running_shoes ("brand","model","slug","series_name","version_number","category","weight","availability","available_from","heel_stack_height","forefoot_stack_height","heel_to_toe_drop","cushioning_level","stability","has_carbon_plate","has_super_foam","price","best_for","release_year","description","source_url","data_source","last_verified","durability_rating","responsiveness_rating","comfort_rating") VALUES ('Nike','Alphafly 4','nike-alphafly-4','Alphafly',4,'racing',NULL,'upcoming','2026-10-29',NULL,NULL,8,'soft','neutral',1,1,279.95,'["racing","long_runs"]',2026,'Upcoming marathon racer with ZoomX LT foam, a carbon Flyplate and redesigned Air Zoom units. Running Warehouse lists orders from October 29, 2026; weight and stack measurements are not yet published. Not independently wear-tested.','https://www.runningwarehouse.com/Nike_Alphafly_4/descpage-NAFL4M1.html','running_warehouse','2026-09-26T00:00:00.000Z',NULL,NULL,NULL) ON CONFLICT(slug) DO NOTHING;
INSERT INTO "_shoe_catalog_import_guard" SELECT CASE WHEN EXISTS(SELECT 1 FROM running_shoes WHERE lower(brand)=lower('Nike') AND lower(model)=lower('Alphafly 3') AND (slug IS NULL OR slug<>'nike-alphafly-3')) THEN 0 ELSE 1 END;
INSERT INTO "_shoe_catalog_import_guard" SELECT CASE WHEN EXISTS(SELECT 1 FROM running_shoes WHERE id=670 AND slug='nike-alphafly-3' AND (("brand" IS 'Nike' AND "model" IS 'Alphafly 3' AND "weight" IS 7 AND "heel_stack_height" IS 40 AND "forefoot_stack_height" IS 32 AND "heel_to_toe_drop" IS 8 AND "price" IS 285 AND "data_source" IS 'curated' AND "last_verified" IS NULL) OR ("brand" IS 'Nike' AND "model" IS 'Alphafly 3' AND "slug" IS 'nike-alphafly-3' AND "series_name" IS 'Alphafly' AND "version_number" IS 3 AND "category" IS 'racing' AND "weight" IS 7 AND "availability" IS 'available' AND "available_from" IS NULL AND "heel_stack_height" IS 40 AND "forefoot_stack_height" IS 32 AND "heel_to_toe_drop" IS 8 AND "cushioning_level" IS 'soft' AND "stability" IS 'neutral' AND "has_carbon_plate" IS 1 AND "has_super_foam" IS 1 AND "price" IS 294.95 AND "best_for" IS '["racing","long_runs"]' AND "release_year" IS 2024 AND "description" IS 'Marathon racer combining ZoomX foam, a carbon Flyplate and forefoot Air Zoom units. Running Warehouse lists a men''s US 9 weight of 7.0 oz and 40/32 mm stack. Price is the checked Sail/Burg Ash/Phantom offer; other colorways may differ.' AND "source_url" IS 'https://www.runningwarehouse.com/Nike_Alphafly_Next_3/descpage-NAFLYM2.html' AND "data_source" IS 'running_warehouse' AND "last_verified" IS '2026-09-26T00:00:00.000Z' AND "durability_rating" IS NULL AND "responsiveness_rating" IS NULL AND "comfort_rating" IS NULL))) THEN 1 ELSE 0 END;
