INSERT INTO "_shoe_catalog_import_guard" SELECT CASE WHEN EXISTS(SELECT 1 FROM running_shoes WHERE id=188 AND slug='adidas-adizero-adios-pro-4' AND (("brand" IS 'Adidas' AND "model" IS 'Adizero Adios Pro 4' AND "weight" IS 7.1 AND "heel_stack_height" IS 32 AND "forefoot_stack_height" IS 26 AND "heel_to_toe_drop" IS 6 AND "price" IS 300 AND "data_source" IS 'curated' AND "last_verified" IS NULL) OR ("brand" IS 'Adidas' AND "model" IS 'Adizero Adios Pro 4' AND "slug" IS 'adidas-adizero-adios-pro-4' AND "series_name" IS 'Adizero Adios Pro' AND "version_number" IS 4 AND "category" IS 'racing' AND "weight" IS 7.1 AND "availability" IS 'available' AND "available_from" IS NULL AND "heel_stack_height" IS 39 AND "forefoot_stack_height" IS 33 AND "heel_to_toe_drop" IS 6 AND "cushioning_level" IS 'soft' AND "stability" IS 'neutral' AND "has_carbon_plate" IS 1 AND "has_super_foam" IS 1 AND "price" IS 199.88 AND "best_for" IS '["racing","long_runs"]' AND "release_year" IS 2025 AND "description" IS 'Road racer using Lightstrike Pro foam and carbon EnergyRods 2.0, not a conventional solid plate. Running Warehouse lists 7.1 oz and 39/33 mm stack for men''s US 9. The $199.88 checked price is a Blue/Silver/Red clearance offer, not MSRP or a guaranteed future price.' AND "source_url" IS 'https://www.runningwarehouse.com/adidas_adizero_Adios_Pro_4/descpage-ADAP4M1.html' AND "data_source" IS 'running_warehouse' AND "last_verified" IS '2026-09-26T00:00:00.000Z' AND "durability_rating" IS NULL AND "responsiveness_rating" IS NULL AND "comfort_rating" IS NULL))) THEN 1 ELSE 0 END;
